package lk.medical.model;
import java.time.LocalDateTime;
public class MedicalRecord { private String id,appointmentId,patientId,doctorId,prescription,feedback; private LocalDateTime createdAt; public MedicalRecord(){} public MedicalRecord(String id,String appointmentId,String patientId,String doctorId,String prescription,String feedback,LocalDateTime createdAt){this.id=id;this.appointmentId=appointmentId;this.patientId=patientId;this.doctorId=doctorId;this.prescription=prescription;this.feedback=feedback;this.createdAt=createdAt;} public String getId(){return id;} public void setId(String v){id=v;} public String getAppointmentId(){return appointmentId;} public void setAppointmentId(String v){appointmentId=v;} public String getPatientId(){return patientId;} public void setPatientId(String v){patientId=v;} public String getDoctorId(){return doctorId;} public void setDoctorId(String v){doctorId=v;} public String getPrescription(){return prescription;} public void setPrescription(String v){prescription=v;} public String getFeedback(){return feedback;} public void setFeedback(String v){feedback=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
